  ui_story_30890101_43_dialog_content = "(Será que o que está acontecendo na Colossus... tem a ver com o grande segredo de Lumópolis?!)",
  ui_story_30890101_44_dialog_content = "Dia Seguinte",
  ui_story_30890101_45_dialog_content = "Quer dizer que está tudo resolvido agora?",
  ui_story_30890101_46_dialog_content = "Isso é incrível, Irridon... Então, o que estava por trás dessas <color=#FFB400>pegadas</color> e da <color=#FFB400>comida desaparecida</color>?",
  ui_story_30890101_47_dialog_content = "Assim como você suspeitava, um Eclipsita de alto nível se infiltrou a bordo quando você parou naquelas ruínas.",
  ui_story_30890101_48_option_content = "E você lidou com isso sozinho?! Você está bem?!",
