  ui_story_30890101_50_dialog_content = "Eu não precisei lutar com isso, simplesmente <color=#FFB400>interroguei</color> isso.",
  ui_story_30890101_51_option_content = "Um Eclipsita de alto nível! Ele escapou?!",
