  ui_story_30890101_56_dialog_content = "Sim, eu me lembro claramente... então foi quando...",
  ui_story_30890101_57_dialog_content = "Sim, ele se esgueirou a bordo.",
  ui_story_30890101_58_dialog_content = "Mas ele não atacou nenhum Auroriano, nem roubou informações da Colossus.",
  ui_story_30890101_59_dialog_content = "Agora, me diga o que você está fazendo aqui ou responda à minha espada.",
  ui_story_30890101_60_dialog_content = "<anim type=Shake><size=35>Eep...</size></anim>",
  ui_story_30890101_61_dialog_content = "Fale!",
  ui_story_30890101_62_dialog_content = "Não, por favor... Ah...",
  ui_story_30890101_63_dialog_content = "Sem sangue ou sinais de combate... Você não está aqui para emboscar a tripulação?",
  ui_story_30890101_64_dialog_content = "Percebi que uma das despensas foi destruída...",
  ui_story_30890101_65_dialog_content = "*Rugido*",
  ui_story_30890101_66_dialog_content = "M-Mim... Com fome... Procurar... Comida... Com fome!",
  ui_story_30890101_67_dialog_content = "Então... Posso... Comer mais...?",
  ui_story_30890101_68_dialog_content = "Comida auroriana... Mmm... Deliciosa...",
  ui_story_30890101_69_dialog_content = "Eu... Não machucar... Não machucar Aurorian!",
  ui_story_30890101_70_dialog_content = "(Um Eclipsite de alto nível... que não machucou ninguém?)",
  ui_story_30890101_71_dialog_content = "Você... Comer? Aqui... Bom...",
  ui_story_30890101_72_dialog_content = "(É... compartilhando sua comida? Isso não é um comportamento normal de Eclipsitas...)",
  ui_story_30890101_73_dialog_content = "(Já vi esses tipos especiais de Eclipsitas antes — seres bondosos e pacíficos que conseguem entender humanos e até mesmo Aurorianos.)",
  ui_story_30890101_74_dialog_content = "(Se for um deles... talvez seja melhor deixá-lo aqui para observação.)",
  ui_story_30890101_75_dialog_content = "Pelo que entendi...",
  ui_story_30890101_76_dialog_content = "Até mesmo um Eclipsita merece um <color=#FFB400>julgamento justo</color>. Você não machucou ninguém, então não tenho motivo para te eliminar.",
  ui_story_30890101_77_dialog_content = "Eh?! Ah... Snif...",
  ui_story_30890101_78_dialog_content = "Mas roubo de comida é um crime punível... E o Colossus poderia ter mais pessoas para limpeza.",
  ui_story_30890101_79_dialog_content = "Se você insistir em comer a comida deles, então limpe este lugar!",
  ui_story_30890101_80_dialog_content = "A-ahn?!",
  ui_story_30890101_81_dialog_content = "No decorrer do meu interrogatório, eu também descobri—",
  ui_story_30890101_82_dialog_content = "Que ele só entrou sorrateiramente a bordo do Colossus e arriscou sua vida por causa de sua extrema necessidade de comida.",
  ui_story_30890101_83_dialog_content = "Seu comportamento não é nada parecido com os Eclipsitas regulares, então eu fiz um teste simples, para limpar a Colossus.",
  ui_story_30890101_84_dialog_content = "E fez isso sem hesitar.",
  ui_story_30890101_85_dialog_content = "Um Eclipsite que gosta de comer comida auroriana... Isso é incrível.",
  ui_story_30890101_86_option_content = "Então... Você não o matou?",
  ui_story_30890101_87_dialog_content = "Dei comida e o mandei seguir seu caminho.",
  ui_story_30890101_88_dialog_content = "A Espada de Empréstimo não matará os inocentes... Então, eu demonstrei piedade.",
  ui_story_30890101_89_option_content = "Mas ainda era um Eclipsite!",
  ui_story_30890101_90_dialog_content = "Talvez um Auroriano maligno seja muito mais assustador do que um Eclipsita inofensivo...",
  ui_story_30890101_91_dialog_content = "Eu nunca deixaria um Auroriano livre se suas mãos estivessem manchadas de sangue... E eu nunca mataria um Eclipsita que não fez nada de errado.",
  ui_story_30890101_92_dialog_content = "Ele... na verdade gosta da comida estranha de Vice?",
  ui_story_30890101_93_dialog_content = "Polvo cozido no leite... Isso pode ser chamado de comida? Que preferência perturbadora...",
  ui_story_30890101_94_dialog_content = "Não importa, estou apenas feliz que ninguém se machucou.",
  ui_story_30890101_95_dialog_content = "Então está tudo bem agora?",
  ui_story_30890101_96_dialog_content = "Como você disse, ninguém se machucou e nada foi danificado.",
  ui_story_30890101_97_dialog_content = "Então todos esses acontecimentos estranhos... foram por causa daquele Eclipsite?",
  ui_story_30890101_98_dialog_content = "Parece ser o caso.",
  ui_story_30890101_99_dialog_content = "T-Tem certeza de que não há mais nada acontecendo?",
  ui_story_30890101_100_dialog_content = "Realizei uma busca completa no Colosso também e não encontrei nada fora do comum.",
  ui_story_30890101_101_dialog_content = "E-É mesmo... Que bom.",
  ui_story_30890101_102_dialog_content = "Esse tempo todo, eu pensei que talvez tivesse a ver com alguns segredos profundos e sombrios de Lumópolis... Não durmo há dias.",
  ui_story_30890101_103_dialog_content = "Por que você pensaria isso?",
  ui_story_30890101_104_dialog_content = "Quando eu contei para Carleen sobre isso, ela ficou pensando por um longo tempo antes de dizer que encontraria alguém para resolver.",
  ui_story_30890101_105_dialog_content = "Carleen está com uma... expressão séria.",
  ui_story_30890101_106_dialog_content = "Hum...",
  ui_story_30890101_107_dialog_content = "Eu pensei que talvez ela soubesse de algo e que não conseguisse lidar com isso sozinha... Então ela pediu alguém tão capaz quanto você!",
  ui_story_30890101_108_dialog_content = "Seja qual for a verdade... Eu não conseguia deixar de sentir que estava de alguma forma ligada a Lumópolis!",
  ui_story_30890101_109_dialog_content = "Você tem uma imaginação incrível.",
  ui_story_30890101_110_dialog_content = "Não há nada de errado em ser cauteloso, mas o assunto foi resolvido. Você pode ficar tranquilo agora.",
  ui_story_30890101_111_dialog_content = "Ah... Eu me pergunto por que a expressão de Carleen estava tão séria, então...",
  ui_story_30890101_112_dialog_content = "Você pode estar pensando demais nas coisas.",
  ui_story_30890101_113_dialog_content = "Tenho quase certeza de que ela estava se perguntando a quem recorrer para resolver esse assunto.",
  ui_story_30890101_114_dialog_content = "O Tribunal de Justiça tem estado muito ocupado ultimamente, e eu estava de férias há muito tempo.",
  ui_story_30890101_X114_dialog_content = "Raramente tiro um tempo para mim, então imagino que ela não quis me incomodar.",
  ui_story_30890101_115_dialog_content = "E não está na minha natureza ignorar uma pessoa necessitada ou um problema que precisa ser resolvido.",
  ui_story_30890101_119_dialog_content = "O Tribunal de Justiça... também não é bem o que eu esperava.",
  ui_story_30890101_120_dialog_content = "Pensei que todos lá passassem os dias lendo documentos, trabalhando em seus assuntos com aquela expressão séria no rosto...",
  ui_story_30890101_121_dialog_content = "Mas quando vi você e os outros do Tribunal de Justiça, percebi que não era esse o caso.",
  ui_story_30890101_122_dialog_content = "Então você ainda acha que eu sou esse tipo de pessoa? Séria e severa?",
  ui_story_30890101_123_dialog_content = "Sim... Quer dizer, não! De jeito nenhum! Nem um pouco!!",
  ui_story_30890101_124_dialog_content = "Quer dizer, você é o Juiz Chefe de Lumópolis! Eu entenderia se você fosse assim, é perfeitamente natural!",
  ui_story_30890101_125_dialog_content = "Não se preocupe, não me surpreende que você pense dessa maneira.",
  ui_story_30890101_126_dialog_content = "Talvez eu também precise fazer algumas mudanças na vida...",
  ui_story_30890101_127_dialog_content = "E se... E se eu tentar uma personalidade diferente a partir de amanhã? Tipo, uma pessoa engraçada?",
  ui_story_30890101_128_dialog_content = "H-Huh??? Q-Quero dizer, não precisa ser tão repentino...",
  ui_story_30890101_129_dialog_content = "Eu também não quero que os outros me achem intimidador, sabe.",
  ui_story_30890101_130_dialog_content = "Eu entendo, mas...",
  ui_story_30890101_131_dialog_content = "Mas você está ótimo do jeito que é! Sério!",
  ui_story_30890601_1_dialog_content = "Você é...",
  ui_story_30890601_2_dialog_content = "<color=#e8d9bb>Estrondo Estrondo Estrondo!</color>",
  ui_story_30890601_3_dialog_content = "Hã?",
  ui_story_30890601_4_dialog_content = "(Sempre fiquei impressionado com os encontros.)",
  ui_story_30890601_5_dialog_content = "(Quando você considera a imensidão do universo e o momento perfeito...)",
  ui_story_30890601_6_dialog_content = "(E a falta de esforço... Um encontro acontece, assim, do nada.)",
  ui_story_30890601_7_dialog_content = "(Assim como agora.)",
  ui_story_30890601_8_dialog_content = "(Antes disso, eu nunca acreditei em nada disso...)",
  ui_story_30890601_9_dialog_content = "(Em um lugar distante de Astra.)",
  ui_story_30890601_10_dialog_content = "(Nesta antiga estação, onde apenas alguns moradores locais de Koufu-jou costumam pisar.)",
  ui_story_30890601_11_dialog_content = "(Eu conheci uma garota com uma roupa local magnífica.)",
  ui_story_30890601_12_dialog_content = "(Ela examinou os cartões-postais à sua frente, pegando um com seus dedos longos e finos.)",
  ui_story_30890601_13_dialog_content = "(Estava frio lá fora, mas gotas de suor escorriam de sua testa.)",
  ui_story_30890601_14_dialog_content = "(Enquanto as flores de cerejeira caíam graciosamente, vi o rosto dela levemente surpreso entre as pétalas que caíam...)",
  ui_story_30890601_15_dialog_content = "PlayerName?",
  ui_story_30890601_16_dialog_content = "Juiz Chefe?",
  ui_story_30890601_17_dialog_content = "Que coincidência. Você também está aqui de férias?",
  ui_story_30890601_18_dialog_content = "É realmente você, Juiz Chefe? Quase não te reconheci.",
  ui_story_30890601_19_dialog_content = "Que há com você?",
  ui_story_30890601_20_dialog_content = "Lembro-me de dizer para você me chamar apenas de Irridon.",
  ui_story_30890601_21_dialog_content = "Além disso, isso não é Lumópolis, então esqueça quem eu sou.",
  ui_story_30890601_22_dialog_content = "Irri... Irridon...",
  ui_story_30890601_23_dialog_content = "*Tosse* Você deixou cair um cartão-postal.",
  ui_story_30890601_24_dialog_content = "Huh? Eu esqueci que estava segurando algo na minha mão...",
  ui_story_30890601_25_dialog_content = "Não se preocupe, eu pego para você.",
  ui_story_30890601_26_dialog_content = "Obrigado, Irridon...",
  ui_story_30890601_27_dialog_content = "Acho que você está realmente diferente em comparação ao seu eu habitual.",
  ui_story_30890601_28_dialog_content = "É por causa de... o que eu estou vestindo?",
  ui_story_30890601_29_dialog_content = "Não é essa a roupa típica de Koufu-jou?",
  ui_story_30890601_30_option_content = "Parece ótimo!",
  ui_story_30890601_31_dialog_content = "Não sei o que mais dizer, mas acho que realmente combina com você!",
  ui_story_30890601_32_option_content = "Parece confortável!",
  ui_story_30890601_33_dialog_content = "Aposto que é perfeito para esse frio!",
  ui_story_30890601_34_option_content = "Parece caro!",
  ui_story_30890601_35_dialog_content = "... Sério?",
  ui_story_30890601_36_dialog_content = "Na verdade, acabei de chegar em Koufu-jou hoje e não esperava que estivesse tão frio aqui.",
  ui_story_30890601_37_dialog_content = "Então comprei um conjunto quando me deparei com ele enquanto passeava.",
  ui_story_30890601_38_dialog_content = "Ahem... Sobre isso... Você também está procurando alguns cartões postais?",
  ui_story_30890601_39_dialog_content = "Bem, ouvi dos moradores locais que, apesar de sua localização remota...",
  ui_story_30890601_40_dialog_content = "Os cartões postais nesta antiga estação são particularmente bonitos.",
  ui_story_30890601_41_dialog_content = "E se você comprar um e escrever uma mensagem para si mesmo... Talvez se torne realidade.",
  ui_story_30890601_42_dialog_content = "Você também ouviu a lenda?",
  ui_story_30890601_43_dialog_content = "Achei que fosse algum tipo de anúncio promocional estranho...",
  ui_story_30890601_44_dialog_content = "Mas talvez realmente exista algum tipo de mágica nos cartões postais daqui.",
  ui_story_30890601_45_dialog_content = "O que te faz dizer isso?",
  ui_story_30890601_46_dialog_content = "Eu estava apenas escrevendo no cartão postal...",
  ui_story_30890601_47_dialog_content = "\"Espero encontrar minha pessoa predestinada em minha jornada.\"",
  ui_story_30890601_48_dialog_content = "O quê?!",
  ui_story_30890601_49_dialog_content = "<color=#e8d9bb>Buzz, buzz... Buzz...</color>",
  ui_story_30890601_50_dialog_content = "Desculpe, é o meu comunicador... Um momento, por favor.",
  ui_story_30890601_51_dialog_content = "Noite Branca lá no alto. O que posso fazer por você, Michenny?",
  ui_story_30890601_52_dialog_content = "(Parece... que o Juiz Chefe está sendo incrivelmente gentil hoje, comparado ao habitual.)",
  ui_story_30890601_53_dialog_content = "(Esta é a magia das férias?)",
  ui_story_30890601_54_dialog_content = "Ohh? Uma nova pista no caso de roubo de Raphael?",
  ui_story_30890601_55_dialog_content = "Quer dizer... está relacionado a ela?",
  ui_story_30890601_56_dialog_content = "(Ela recebeu alguma notícia ruim? A expressão de Irridon de repente ficou séria...)",
  ui_story_30890601_57_dialog_content = "Bem, uhmm, ok. Entendi, acontece que eu... *Tosse*.",
  ui_story_30890601_58_dialog_content = "(... Por que ela olhou para mim e virou-se?)",
  ui_story_30890601_59_dialog_content = "Desculpe tê-lo deixado esperando.",
  ui_story_30890601_60_dialog_content = "Irridon, está tudo... bem?",
  ui_story_30890601_61_dialog_content = "Por que pergunta?",
  ui_story_30890601_62_dialog_content = "Nada. Talvez seja só eu...",
  ui_story_30890601_63_dialog_content = "Você se lembrou de algo que fez?",
  ui_story_30890601_64_dialog_content = "Não... nada...",
  ui_story_30890601_65_dialog_content = "(Ela voltou como Juíza Chefe...? Ela é claramente uma pessoa diferente de agora há pouco.)",
  ui_story_30890601_66_dialog_content = "Por que você não pensa um pouco mais? Tem certeza de que não fez nada?",
  ui_story_30890601_67_dialog_content = "Bem... Na verdade, eu deveria terminar o resto do trabalho hoje...",
  ui_story_30890601_68_dialog_content = "Mas em vez disso, eu cabulei o trabalho e estou vagando por aí.",
  ui_story_30890601_69_dialog_content = "Então, você faltou ao trabalho?",
  ui_story_30890601_70_dialog_content = "Mas eu acredito que há algo mais. Tente pensar novamente.",
  ui_story_30890601_71_dialog_content = "Ontem, Vice cozinhou e eu fingi comer, mas na verdade eu não comi...",
  ui_story_30890601_72_dialog_content = "Algo mais?",
  ui_story_30890601_73_dialog_content = "Não respondi ao e-mail de Charon...",
  ui_story_30890601_74_dialog_content = "Aceitei um presente de um estranho...",
  ui_story_30890601_75_dialog_content = "Eu não lavei meu rosto de manhã...",
  ui_story_30890601_76_dialog_content = "Espera... O que você disse?",
  ui_story_30890601_77_dialog_content = "Desculpe... Eu não lavei meu rosto esta manhã.",
  ui_story_30890601_78_dialog_content = "Embora isso seja chocante, o que você disse antes disso?",
  ui_story_30890601_79_dialog_content = "Aceitei um presente... de um estranho?",
  ui_story_30890601_80_dialog_content = "Onde? Quando?",
  ui_story_30890601_81_dialog_content = "Em... Lumópolis. Apenas no outro dia, era a noite antes de eu deixar Lumópolis.",
  ui_story_30890601_82_dialog_content = "Onde está o presente agora?",
  ui_story_30890601_83_dialog_content = "Atchiii!",
  ui_story_30890601_84_dialog_content = "Tá com frio?",
  ui_story_30890601_85_dialog_content = "Talvez... e provavelmente estou malvestido.",
  ui_story_30890601_86_dialog_content = "Por que não pegar outra roupa?",
  ui_story_30890601_87_dialog_content = "(Eu não posso simplesmente dizer a ela que não tenho dinheiro suficiente...)",
  ui_story_30890601_88_dialog_content = "*Tosse* Eu sei que está meio bagunçado, mas... aqui está o armazém.",
  ui_story_30890601_89_dialog_content = "Depois de receber o presente, você o abriu para ver o que tinha dentro?",
  ui_story_30890601_90_dialog_content = "Eu estava com medo de que fosse uma daquelas brincadeiras, então guardei no armazém...",
  ui_story_30890601_91_dialog_content = "Você costuma receber presentes de brincalhões?",
  ui_story_30890601_92_dialog_content = "*Tosse* Isso... não é o ponto.",
  ui_story_30890601_93_dialog_content = "Há... algo de errado com o presente que recebi?",
  ui_story_30890601_94_dialog_content = "Recentemente, uma gangue de ladrões cometeu uma série de assaltos em Lumópolis.",
  ui_story_30890601_95_dialog_content = "Então, o presente que você recebeu pode ser produto de roubo!",
  ui_story_30890601_96_dialog_content = "Atchim... Vou procurar isso!",
  ui_story_30890601_97_dialog_content = "É esse aí à sua esquerda?",
  ui_story_30890601_98_dialog_content = "Vejamos...",
  ui_story_30890601_99_dialog_content = "<color=#e8d9bb>Ding! Dang! Clang! Bang!</color>",
  ui_story_30890601_100_dialog_content = "*Tosse* Quem colocou todas essas peças de máquinas quebradas aqui...?",
  ui_story_30890601_101_dialog_content = "Não é isso...? Ali, na sua frente.",
  ui_story_30890601_102_dialog_content = "<color=#e8d9bb>Ding! Dang! Clang! Bang!</color>",
  ui_story_30890601_103_dialog_content = "O que é aquela coisa parecida com um grampo?",
  ui_story_30890601_104_dialog_content = "Haha, este é o meu apertador de mão precioso! Eu uso ele para testar minha força de vez em quando!",
  ui_story_30890601_105_dialog_content = "Huh? Por que isso é tão fácil?!",
  ui_story_30890601_106_dialog_content = "Atchim... Eu não percebi que fiquei mais forte.",
  ui_story_30890601_107_dialog_content = "Espere, isso não pode ser. Alguém deve ter estragado meu pegador!",
  ui_story_30890601_108_dialog_content = "... Acho que você deveria limpar seu nariz primeiro.",
  ui_story_30890601_109_dialog_content = "Atchim! Obrigado pelo lembrete, Juiz Chefe...",
  ui_story_30890601_110_dialog_content = "O que é aquela caixa à sua direita?",
  ui_story_30890601_111_dialog_content = "Ah, sim! É isso! É o presente que recebi do desconhecido.",
  ui_story_30890601_112_dialog_content = "Deixa eu trazer para você dar uma olhada!",
  ui_story_30890601_113_dialog_content = "Não tenha pressa e preste atenção por onde está indo.",
  ui_story_30890601_114_dialog_content = "<color=#e8d9bb>Ding! Dang! Clang! Bang!</color>",
  ui_story_30890601_115_dialog_content = "<size=45><color=#e8d9bb>Estrondo—!</color></size>",
  ui_story_30890601_116_dialog_content = "... PlayerName, você está bem?",
  ui_story_30890601_117_dialog_content = "Eu sinto muito—mesmo, Juiz Chefe.",
  ui_story_30890601_118_dialog_content = "Caí bem em cima do presente e parece que o esmaguei.",
  ui_story_30890601_119_dialog_content = "Mas é estranho. Mesmo que eu tenha caído...",
  ui_story_30890601_120_dialog_content = "Não estou machucado...",
  ui_story_30890601_121_dialog_content = "E minhas costas não estão doloridas, minhas pernas não doem e nem sinto mais vontade de espirrar!",
  ui_story_30890601_122_dialog_content = "O que está acontecendo...?",
  ui_story_30890601_123_dialog_content = "Você não entende? Ela explodiu e te curou. O que você acha que é?",
  ui_story_30890601_124_dialog_content = "Será que isso é... o Cartucho de Água Benta de Raphael?!",
  ui_story_30890601_125_dialog_content = "Você quer dizer que o estranho vestido de preto era Raphael?",
  ui_story_30890601_126_dialog_content = "Se foi dado a você por Raphael, não haveria necessidade de eu realizar uma investigação.",
  ui_story_30890601_127_dialog_content = "Você está certo, seriam necessários vários Raphaels empilhados uns sobre os outros para ser tão alto quanto o estranho.",
  ui_story_30890601_128_dialog_content = "Então, você está dizendo que um estranho roubou as coisas de Raphael e deu para mim? Mas por quê...?",
  ui_story_30890601_129_dialog_content = "Você se lembra de mais alguma coisa sobre o estranho?",
  ui_story_30890601_130_dialog_content = "Lembro que o estranho estava envolto bem apertado da cabeça aos pés em preto.",
  ui_story_30890601_131_dialog_content = "E eles andavam meio cambaleantes, como se a parte superior e inferior do corpo não estivessem conectadas.",
  ui_story_30890601_132_dialog_content = "Depois de me entregar o presente, eles simplesmente se viraram e foram embora...",
  ui_story_30890601_133_dialog_content = "Cambaleante... Você sentiu cheiro de álcool?",
  ui_story_30890601_134_dialog_content = "De jeito nenhum... Mas logo antes do estranho partir, ouvi um corvo parecido com uma galinha!",
  ui_story_30890601_135_dialog_content = "Agora que penso nisso, é realmente estranho!",
  ui_story_30890601_136_dialog_content = "Entendo...",
  ui_story_30890601_137_dialog_content = "Juiz Chefe... Você sabe quem era o estranho de preto?",
  ui_story_30890601_138_dialog_content = "Só tem um que me vem à mente, e esse é...",
  ui_story_30890601_139_dialog_content = "Keating!",
  ui_story_30890601_140_dialog_content = "Keating? Como? Você teria que empilhá-los para ficarem tão altos quanto aquele estranho de preto...",
  ui_story_30890601_141_dialog_content = "Espere, você quer dizer que eles se empilharam para fingir ser o estranho de preto?!",
  ui_story_30890601_142_dialog_content = "Mas por que eles se esforçaram tanto para me dar um presente assim...?",
  ui_story_30890601_143_dialog_content = "O motivo ainda é uma incógnita... Você viu se havia alguma mensagem deixada na caixa do presente?",
  ui_story_30890601_144_dialog_content = "Deixa eu ver... Espere... Realmente tem um bilhete! Está escrito...",
  ui_story_30890601_145_dialog_content = "\"Querida pessoa pobre e digna de pena. Não fique triste mais.\"",
  ui_story_30890601_146_dialog_content = "\"Aqui está um presente para ajudá-lo a ficar rico.\"",
  ui_story_30890601_147_dialog_content = "\"De: GNITAEK.\"",
  ui_story_30890601_148_dialog_content = "Ok... Até eu estou convencido de que é Keating agora.",
  ui_story_30890601_149_dialog_content = "*suspiros* Essas crianças...",
  ui_story_30890601_150_dialog_content = "Parece que eles precisam de uma educação adequada... Para que possam fazer o bem de maneira correta e honesta.",
  ui_story_30890601_151_dialog_content = "Mas por quê? Por que eles acham que eu preciso de ajuda?",
  ui_story_30890601_152_dialog_content = "É porque eu estou sempre usando as mesmas roupas? Mas...",
  ui_story_30890601_153_dialog_content = "Noite Branca nas alturas! Eu oficialmente declaro este caso encerrado.",
  ui_story_30890601_154_dialog_content = "Haha! Vamos, PlayerName!",
  ui_story_30890601_155_dialog_content = "Hã? Para onde? Você quer dizer...",
  ui_story_30890601_156_option_content = "Prisão de Lumópolis?",
  ui_story_30890601_157_dialog_content = "Bem, eu já sei que foi um mal-entendido.",
  ui_story_30890601_158_dialog_content = "Esta é uma rara férias, então vamos continuar nossa viagem para Koufu-jou.",
  ui_story_30890601_159_option_content = "A estação vende cartões postais?",
  ui_story_30890601_160_dialog_content = "Ahh, você não teve a chance de comprar nada por causa do mal-entendido agora há pouco, certo?",
  ui_story_30890601_161_dialog_content = "Ok, no entanto...",
  ui_story_30890601_162_dialog_content = "Por favor, não se preocupe com o dinheiro. Hoje é tudo por minha conta!",
  ui_story_30890601_163_dialog_content = "Será... será que todo mundo realmente acha que eu estou sem dinheiro...?",
  ui_story_30890602_1_dialog_content = "<color=#e8d9bb>Vuuuuush—</color>",
  ui_story_30890602_2_dialog_content = "(Uma brisa suave sopra no ar. À minha frente está uma garota com olhos e cabelos tão dourados e ardentes quanto o sol.)",
  ui_story_30890602_3_dialog_content = "(Para todos os outros, ela é uma Juíza Chefe altiva, distante e sem sorrisos.)",
  ui_story_30890602_4_dialog_content = "(Mas agora, ela está me mostrando um lado completamente diferente dela, um que ela mantém bem escondido sob sua máscara...)",
  ui_story_30890602_5_dialog_content = "PlayerName...",
  ui_story_30890602_6_dialog_content = "É realmente tudo bem?",
  ui_story_30890602_7_dialog_content = "<color=#e8d9bb>Mais cedo naquele dia</color>",
  ui_story_30890602_8_dialog_content = "Arf, arf... Desculpe pela espera!",
  ui_story_30890602_9_dialog_content = "Você não precisa se desculpar. Eu não esperei muito tempo.",
  ui_story_30890602_10_dialog_content = "Se alguma coisa, eu deveria agradecer por você se juntar a mim para uma xícara de chá.",
  ui_story_30890602_11_dialog_content = "Aham, para ser sincero, eu queria te visitar há algum tempo, só para ter certeza de que você está bem.",
  ui_story_30890602_12_dialog_content = "Eu te deixei preocupado, não foi...?",
  ui_story_30890602_13_dialog_content = "Mas posso garantir que estou perfeitamente bem. Além disso, como Juíza Chefe de Lumopolis, não posso me dar ao luxo de ser derrotada facilmente.",
  ui_story_30890602_14_dialog_content = "Após acordar daquele longo e confuso sonho, acho que finalmente encontrei meu caminho futuro.",
  ui_story_30890602_15_dialog_content = "Um a um, estou lentamente começando a resolver os problemas do meu passado que antes me deixavam desamparado e perdido.",
  ui_story_30890602_16_dialog_content = "Antes, eu me forçava a ser o Juiz Chefe perfeito, digno das esperanças e expectativas de todos. Mas agora...",
  ui_story_30890602_17_dialog_content = "Finalmente percebo que não preciso mais fingir ser alguém. Eu sou quem sou, e isso é mais do que suficiente.",
  ui_story_30890602_18_dialog_content = "Então obrigado, PlayerName. Obrigado por me acordar desse pesadelo.",
  ui_story_30890602_19_option_content = "De nada!",
  ui_story_30890602_20_dialog_content = "Eu estava apenas fazendo o que deveria fazer!",
  ui_story_30890602_21_option_content = "Não há necessidade de me agradecer...",
  ui_story_30890602_22_dialog_content = "Eu não fiz realmente nada... Você é quem se salvou!",
  ui_story_30890602_23_dialog_content = "Hahaha! Tão humilde como sempre.",
  ui_story_30890602_24_dialog_content = "Mudando de assunto, eu estava esperando que você pudesse me acompanhar para ver uma certa pessoa hoje.",
  ui_story_30890602_25_dialog_content = "Ainda me sinto um pouco culpado e simplesmente não consigo dar esse primeiro passo sozinho.",
  ui_story_30890602_26_dialog_content = "Ah... É por isso que você está usando uma roupa diferente hoje?",
  ui_story_30890602_27_dialog_content = "Sim. Essas são minhas roupas antigas de quando eu ainda era um cavaleiro. Estou surpreso que ainda sirvam tão bem depois de todos esses anos.",
  ui_story_30890602_28_dialog_content = "Mas mesmo naquela época, eu ainda estava evitando o problema que havia enterrado bem no fundo do meu coração.",
  ui_story_30890602_29_dialog_content = "Anos se passaram e as pessoas mudaram, mas o problema ainda está inextricavelmente ligado àquele lugar.",
  ui_story_30890602_30_dialog_content = "Se meu pesadelo me mostrou algo, é que chegou a hora de enfrentar meus demônios e resolver esse problema de uma vez por todas.",
  ui_story_30890602_31_dialog_content = "Mas sem você lá para cuidar de mim, receio que não terei coragem para fazer isso.",
  ui_story_30890602_32_dialog_content = "Você já derrotou seu pesadelo e recuperou seu verdadeiro eu... O que mais poderia assustá-lo agora?",
  ui_story_30890602_33_option_content = "A menos...",
  ui_story_30890602_34_dialog_content = "É o seu pai?",
  ui_story_30890602_35_dialog_content = "Sim.",
  ui_story_30890602_36_option_content = "Eu simplesmente não entendo...",
  ui_story_30890602_37_dialog_content = "É... meu pai.",
  ui_story_30890602_38_dialog_content = "Me envergonha dizer isso, mas mesmo que meu pai tenha morrido para me proteger... Eu nunca fui prestar meus respeitos no túmulo dele. Nem mesmo uma vez.",
  ui_story_30890602_39_dialog_content = "Eu... Ainda não consigo enfrentá-lo. Toda vez que passo pelo cemitério, me sinto compelido a andar o mais rápido possível.",
  ui_story_30890602_40_dialog_content = "Mas agora... Você tem algo importante para dizer a ele, não tem?",
  ui_story_30890602_41_dialog_content = "Eu sei, e é algo que precisa ser dito... Mas ainda estou com medo.",
  ui_story_30890602_42_dialog_content = "Então eu vou com você! Embora não obtenhamos uma resposta dele agora, o simples ato de contar a ele deve fornecer a resposta que você precisa!",
  ui_story_30890602_43_dialog_content = "PlayerName... Eu sabia que estava certo em pedir sua ajuda.",
  ui_story_30890602_44_dialog_content = "Você pretende trazer algo para ele?",
  ui_story_30890602_45_dialog_content = "Hmm... Não. Pai sempre odiava receber presentes, especialmente os valiosos.",
  ui_story_30890602_46_dialog_content = "Mas como alguém pode odiar receber um presente? Hum... Ele tinha algum hobby no passado?",
  ui_story_30890602_47_dialog_content = "Não realmente. A paixão do pai sempre foi o trabalho dele, mas quando ele não estava trabalhando, ele cuidava das flores neste jardim...",
  ui_story_30890602_48_dialog_content = "Às vezes, eu até sentia inveja daquelas flores. A única vez que meu pai demonstrou algum tipo de compaixão foi quando cuidava delas.",
  ui_story_30890602_49_dialog_content = "E, você é o responsável por cuidar dessas flores agora?",
  ui_story_30890602_50_dialog_content = "Sim... Irônico, não é?",
  ui_story_30890602_51_dialog_content = "De jeito nenhum! Essas flores parecem saudáveis e lindas para mim!",
  ui_story_30890602_52_dialog_content = "Então, por que você não escolhe alguns para o seu pai? Assim, ele também pode ver como você cuidou bem deles.",
  ui_story_30890602_53_dialog_content = "Sério?",
  ui_story_30890602_54_dialog_content = "\"Aqui jaz Rodell Novek...\" Irridon, eu o encontrei!",
  ui_story_30890602_55_dialog_content = "Huh? Ei, você está bem...?",
  ui_story_30890602_56_dialog_content = "...",
  ui_story_30890602_57_dialog_content = "Eu sei que isso deve ser realmente difícil para você. Posso acompanhá-lo de volta, se é isso que você deseja...",
  ui_story_30890602_58_dialog_content = "Não, PlayerName. Acho que finalmente estou pronto.",
  ui_story_30890602_59_dialog_content = "Ufa...",
  ui_story_30890602_60_dialog_content = "Olá, Pai. Sou eu, Irridon... Desculpe a demora. Finalmente reuni coragem para te ver.",
  ui_story_30890602_61_dialog_content = "Todos esses anos, só de pensar em enfrentar você, me enchia de vergonha. Eu tinha medo de que você ainda me visse como \"inútil\" por não demonstrar crescimento.",
  ui_story_30890602_62_dialog_content = "Ainda não entendo por que você sacrificaria sua própria vida para salvar uma pessoa \"inútil\" como eu...",
  ui_story_30890602_63_dialog_content = "Mas eu rezo para que um dia, quando eu finalmente corresponder às suas expectativas, eu possa dizer que fiz isso de cabeça erguida!",
  ui_story_30890602_64_dialog_content = "Infelizmente... Parece que esse dia ainda está muito longe.",
  ui_story_30890602_65_dialog_content = "Mas mesmo assim, não tenho mais medo. Eu queria te dizer que depois de todos esses anos... não sou mais tão inútil quanto pensava.",
  ui_story_30890602_66_dialog_content = "Agora sou o Juiz Chefe, alguém seguro em seus objetivos e convicções.",
  ui_story_30890602_67_dialog_content = "Mesmo que eu não seja exatamente quem você queria que eu fosse, vou continuar me esforçando para me tornar a melhor versão de mim mesmo...",
  ui_story_30890602_68_dialog_content = "Porque assim como você, Pai... Eu não desejo nada mais do que proteger esta cidade pura e bela no céu.",
  ui_story_30890602_69_dialog_content = "Finalmente entendo agora. Você nunca me odiou; você simplesmente estava usando o método mais indireto de mostrar seu amor por mim...",
  ui_story_30890602_70_dialog_content = "Então, por favor, continue cuidando de mim. Vou continuar seguindo em frente... Mas do meu próprio jeito.",
  ui_story_30890602_71_dialog_content = "Eu realmente acredito... que esta é a melhor maneira de retribuir a você...",
  ui_story_30890602_72_dialog_content = "<color=#e8d9bb>Vuuuuush—</color>",
  ui_story_30890602_73_dialog_content = "PlayerName... Será que está realmente tudo bem?",
  ui_story_30890602_74_option_content = "Claro que não!",
  ui_story_30890602_75_option_content = "Foi perfeito!",
  ui_story_30890602_76_dialog_content = "Tenho certeza que ele te ouviu, alto e claro!",
  ui_story_30890602_77_dialog_content = "Você está certo... Tenho certeza que ele ouviu cada palavra."
}
return config
